    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index or length");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
            i++;
        } else if (ch <= 0x7FF) {
            size += 2;
            i++;
