public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                // Trailing backslash, treat as literal
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            if (next == '\\') {
                sb.append('\\');
                i++; // skip the escaped backslash
            } else if (next == 'u') {
                // Unicode escape \uXXXX
                if (i + 5 >= str.length()) {
                    throw new Exception("Invalid unicode escape sequence at position " + i);
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid unicode escape sequence: \\u" + hex);
                }
                i += 5; // skip \uXXXX
            } else if (next >= '0' && next <= '7') {
                // Octal escape \ooo (up to 3 digits)
                int j = i + 1;
                int end = j;
                while (end < str.length() && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                    end++;
                }
                String oct = str.substring(j, end);
                try {
                    int code = Integer.parseInt(oct, 8);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid octal escape sequence: \\" + oct);
                }
                i = end - 1; // adjust index
            } else {
                // Standard single-character escapes
                switch (next) {
                    case 'b': sb.append('\b'); break;
                    case 't': sb.append('\t'); break;
                    case 'n': sb.append('\n'); break;
                    case 'f': sb.append('\f'); break;
                    case 'r': sb.append('\r'); break;
                    case '\'': sb.append('\''); break;
                    case '\"': sb.append('\"'); break;
                    case '\\': sb.append('\\'); break;
                    default:
                        // Unknown escape, keep the character as is
                        sb.append(next);
                }
                i++; // skip the escape character
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
